/**
 * @method
 * @name scwin.enterDisclsConfirmLogin
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.enterDisclsConfirmLogin = async function () {
    /* sdd-asis-lifecycle:begin enterDisclsConfirmLogin — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (event.keyCode == 13) {
        await scwin.fnDisclsConfirmLogin();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnDisclsConfirmLogin
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnDisclsConfirmLogin = async function () {
    /* sdd-asis-lifecycle:begin fnDisclsConfirmLogin — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($('#ipt_sPw', $('#disclsConfirm')).val() === "") {
        scwin.alertDiscls("화면접근번호를 입력하십시오.");
        $c.util.getComponent("ipt_sPw").focus();
        return;
    }
    (document.disclsConfirm || { elements: [] }).action = "/combasinfo/comOvrvw.do?method=disclsConfirmLogin";
    (document.disclsConfirm || { elements: [] }).target = "selfWin";

    await scwin.tx_fnDisclsConfirmLogin();
    /* sdd-asis-lifecycle:end */
};


