    layerUI2('#layerUi');
    layerUI2('.layerUi');
    $('#txt_pAlertDisclsText')[0].innerText = msg;
    scwin.disclsAlertMsg.setStyle("display", "");
    /* sdd-asis-lifecycle:end */
};


